class TrackyReadPDO extends PDO
{
    public bool $readGuard=false,$ddlGuard=false;
    public int $writes=0,$ddl=0,$selects=0;
    public $onRead=null;
    private function guard(string $sql): void
    {
        if($this->ddlGuard&&preg_match('/^\s*(CREATE|ALTER|DROP)\b/i',$sql)){$this->ddl++;throw new RuntimeException('Unexpected schema write.');}
        if($this->readGuard&&!preg_match('/^\s*(SELECT|PRAGMA)\b/i',$sql)){$this->writes++;throw new RuntimeException('Unexpected read-side write.');}
        if(preg_match('/^\s*SELECT\b/i',$sql)){$this->selects++;if($this->onRead)($this->onRead)($sql);}
    }
    public function exec(string $sql): int|false{$this->guard($sql);return parent::exec($sql);}
    public function query(string $sql,?int $mode=null,mixed ...$args): PDOStatement|false{$this->guard($sql);return $mode===null?parent::query($sql):parent::query($sql,$mode,...$args);}
    public function prepare(string $sql,array $options=[]): PDOStatement|false{$this->guard($sql);return parent::prepare($sql,$options);}
}
